import type { Answer, Result, Sources } from './app.contract.d.ts';

export const grants = '';

// Mirrors the fields of the original app. Persistence and editing are separate work.
export interface ExperimentPhoto {
  id: string;
  uri: string;
  fileName: string | null;
  mimeType: string | null;
  width: number;
  height: number;
}
export interface ExperimentResult {
  id: string;
  recordedAt: string;
  notes: string;
  photoAssets: ExperimentPhoto[];
}
export interface Experiment {
  id: string;
  title: string;
  category: string;
  hypothesis: string;
  procedure: string;
  dataPlan: string;
  observationsNotes: string;
  resultEntries: ExperimentResult[];
  notes: string;
  conclusionNotes: string;
  plannedAttachmentCount: number;
  photoAssets: ExperimentPhoto[];
  status: 'active' | 'complete';
  createdAt: string;
  updatedAt: string;
}

const examples: Experiment[] = [{
  id: 'example-beans', title: 'Bean sprouts under different light conditions (Example)',
  category: 'Botany', hypothesis: 'Bean sprouts exposed to indirect daylight will grow taller than sprouts kept under a desk lamp for the same duration.',
  procedure: 'Grow matching bean seeds in two trays under different light and measure daily.',
  dataPlan: 'Record height, color changes, and moisture daily.',
  observationsNotes: 'Window tray currently shows slightly faster growth after the first 48 hours.',
  resultEntries: [], notes: '', conclusionNotes: '', plannedAttachmentCount: 0, photoAssets: [],
  status: 'active', createdAt: '2026-06-14T09:30:00.000Z', updatedAt: '2026-06-16T17:10:00.000Z',
}];

const sources: Sources = {
  listExperiments: (): Result<'listExperiments'> => examples.map((experiment) => ({
    id: experiment.id, title: experiment.title, category: experiment.category,
    status: experiment.status, hypothesis: experiment.hypothesis,
    observations: experiment.observationsNotes || 'No observations recorded yet.',
  })),
};
export const answer: Answer = (source, args, store, storage, native) =>
  sources[source](args, store, storage, native);

#!/bin/sh
':' //; if [ -n "$BUN" ]; then exec "$BUN" "$0" "$@"; elif [ -x "$HOME/.bun-1.4.2/bin/bun" ]; then exec "$HOME/.bun-1.4.2/bin/bun" "$0" "$@"; else exec '<local>/mrdj-dev-suite-i2Workspace\generated\exact-jenny\toolchains\bun\bun-windows-x64\bun.exe' "$0" "$@"; fi
// experimemo-exact's commands: `bun exact.mjs --help` lists the verbs, `bun exact.mjs <verb> --help` a verb's flags.
// They live in the exact2 checkout named by EXACT2 (default ../../../temp/exact-upstream), in its
// scripts/app-cli.mjs. Generated by `exact new`; `bun exact.mjs update` rewrites this file, the crates.io
// patches, the toolchain and the exact2 dependency paths. The app's own verbs are app.json's `commands`.
import { spawnSync } from 'node:child_process';
import { existsSync, realpathSync } from 'node:fs';
import { basename, dirname, relative, resolve } from 'node:path';

const path = process.env.EXACT2 ?? "../../../temp/exact-upstream";
const found = (base) => existsSync(resolve(base, path, 'scripts/app-cli.mjs'));
// In a linked git worktree the path is from the app's folder in the main working tree, as `update` writes it there. Only
// a common dir that is <main>/.git names that tree; a bare repository's, a submodule's or a --separate-git-dir one does not.
const git = process.env.EXACT2 || found(import.meta.dir) ? null : spawnSync('git', ['rev-parse', '--path-format=absolute', '--show-toplevel', '--git-common-dir'], { cwd: import.meta.dir, encoding: 'utf8', env: Object.fromEntries(Object.entries(process.env).filter(([key]) => !key.startsWith('GIT_'))) });
const [top, common] = git?.status === 0 ? git.stdout.trim().split('\n').map((line) => realpathSync(line.trim())) : [];
const main = basename(common ?? '') === '.git' ? resolve(dirname(common), relative(top, realpathSync(import.meta.dir))) : null;
const EXACT2 = resolve(main && found(main) ? main : import.meta.dir, path);
const cli = resolve(EXACT2, 'scripts/app-cli.mjs');
if (!existsSync(cli)) { console.error(`no exact2 at ${EXACT2} (no scripts/app-cli.mjs): EXACT2 names the checkout`); process.exit(1); }
const { ensureBun } = await import(resolve(EXACT2, 'scripts/bun.mjs'));
ensureBun("1.4.2");
const { run } = await import(cli);
process.exit(await run({ dir: import.meta.dir, name: "experimemo-exact", exact2: EXACT2, args: process.argv.slice(2) }));

