// ---------------------------------------------------------------------------

export type ExperimentStatus = 'active' | 'complete';

export interface ExperimentPhotoAsset {
  id: string;
  uri: string;
  fileName: string | null;
  mimeType: string | null;
  width: number;
  height: number;
}

export interface ExperimentResultEntry {
  id: string;
  recordedAt: string;
  notes: string;
  photoAssets: ExperimentPhotoAsset[];
