// ---------------------------------------------------------------------------
// Helpers & Normalization
// ---------------------------------------------------------------------------


// ---------------------------------------------------------------------------
// The file store. One JSON file, read and written whole, through storage.fs.
//
// - Every exported operation, the first-run seeding included, runs one at a time through a
//   single queue, so two overlapping calls (an autosave and a status change, a create and
//   a delete) each read what the one before wrote: no write is lost to a stale read.
// - Every write is read back and compared before the operation returns, inside the same
//   turn of the queue; a file that does not hold what was written is an error.
// - Every failure throws. Nothing falls back to memory, so a caller never reports a save
//   the file does not hold. Time and ids are arguments (a data source has no clock or random).
//
// The queue is this module's: it serialises calls made in one JavaScript realm, which is
// how Exact runs a data module's sources. A second process writing the same file is not covered.
// ---------------------------------------------------------------------------

export const EXPERIMENT_FS_PATH = 'app:/data/experiments.json';

export interface FileSystem {
  readFile(path: string): Promise<ArrayBuffer>;
  atomicWriteFile(path: string, data: ArrayBuffer | Uint8Array): Promise<void>;
  // Photo files only: removing an unreferenced one and finding strays. Absent on a fake, so optional.
  rm?(path: string): Promise<void>;
  readdir?(path: string): Promise<string[]>;
}
export interface Storage {
  readonly fs: FileSystem;
}

/** The fields an editor owns; results and photos are kept as the record holds them. */
export type ExperimentFields = Omit<ExperimentInput, 'resultEntries' | 'photoAssets'>;

interface FileState {
  bootstrapped: boolean;
  experiments: ExperimentRecord[];
}

const clone = (r: ExperimentRecord): ExperimentRecord => JSON.parse(JSON.stringify(r));
const byUpdated = (xs: ExperimentRecord[]) => [...xs].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));

let tail: Promise<unknown> = Promise.resolve();

/** Runs `work` after every earlier operation has finished, whether it succeeded or failed. */
function serial<T>(work: () => Promise<T>): Promise<T> {
  const run = tail.then(work, work);
  tail = run.catch(() => undefined);
  return run;
}

/** The file exists but does not hold a valid state. Nothing is changed or replaced when this is thrown. */
export class StoreCorruptError extends Error {
  constructor(detail: string) {
    super(`The experiment file is damaged (${detail}), so nothing was changed. Reset the app to start over.`);
  }
}

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
const isString = (v: unknown): v is string => typeof v === 'string';
const isNumber = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);
const isStamp = (v: unknown): v is string => isString(v) && !Number.isNaN(Date.parse(v));
const nullableString = (v: unknown) => v === null || isString(v);

function checkPhotos(v: unknown, where: string): void {
  if (!Array.isArray(v)) throw new StoreCorruptError(`${where} has no photo list`);
  for (const p of v) {
    if (
      !isObject(p) ||
      !isString(p.id) ||
      !isString(p.uri) ||
      !nullableString(p.fileName) ||
      !nullableString(p.mimeType) ||
      !isNumber(p.width) ||
      !isNumber(p.height)
    ) {
      throw new StoreCorruptError(`${where} has a malformed photo`);
    }
  }
}

function checkRecord(r: unknown, index: number): void {
  if (!isObject(r) || !isString(r.id) || r.id === '') throw new StoreCorruptError(`record ${index + 1} has no id`);
  const named = `record "${r.id}"`;
  for (const key of ['title', 'category', 'hypothesis', 'procedure', 'dataPlan', 'observationsNotes', 'notes', 'conclusionNotes'] as const) {
    if (!isString(r[key])) throw new StoreCorruptError(`${named} has a bad ${key}`);
  }
  if (!isNumber(r.plannedAttachmentCount) || r.plannedAttachmentCount < 0) throw new StoreCorruptError(`${named} has a bad photo count`);
  if (r.status !== 'active' && r.status !== 'complete') throw new StoreCorruptError(`${named} has a bad status`);
  if (!isStamp(r.createdAt) || !isStamp(r.updatedAt)) throw new StoreCorruptError(`${named} has a bad date`);
  checkPhotos(r.photoAssets, named);
  if (!Array.isArray(r.resultEntries)) throw new StoreCorruptError(`${named} has no result list`);
  const seen = new Set<string>();
  for (const e of r.resultEntries) {
    if (!isObject(e) || !isString(e.id) || e.id === '' || seen.has(e.id)) throw new StoreCorruptError(`${named} has a bad result id`);
    seen.add(e.id);
    if (!isString(e.notes) || !isStamp(e.recordedAt)) throw new StoreCorruptError(`${named} has a malformed result`);
    checkPhotos(e.photoAssets, `${named} result`);
  }
}

/**
 * Only a file that does not exist is a first run (ENOENT). A file that is there must be a
 * complete, valid state: anything else throws and is left exactly as it is.
 */
async function read(storage: Storage): Promise<FileState> {
  let bytes: ArrayBuffer;
  try {
    bytes = await storage.fs.readFile(EXPERIMENT_FS_PATH);
  } catch (e) {
    if ((e as { code?: string })?.code === 'ENOENT') return { bootstrapped: false, experiments: [] };
    throw e;
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
  } catch {
    throw new StoreCorruptError('it is not readable data');
  }
  if (!isObject(parsed)) throw new StoreCorruptError('it is not an object');
  if (parsed.bootstrapped !== true) throw new StoreCorruptError('it is missing its setup marker');
  if (!Array.isArray(parsed.experiments)) throw new StoreCorruptError('it has no experiment list');
  const ids = new Set<string>();
  parsed.experiments.forEach((r, i) => {
    checkRecord(r, i);
    const id = (r as ExperimentRecord).id;
    if (ids.has(id)) throw new StoreCorruptError(`id "${id}" appears twice`);
    ids.add(id);
  });
  return { bootstrapped: true, experiments: parsed.experiments as ExperimentRecord[] };
}

export const PHOTOS_DIR = 'app:/data/photos';

const photoUris = (state: FileState): Set<string> => {
  const uris = new Set<string>();
  for (const e of state.experiments) {
    e.photoAssets.forEach((p) => uris.add(p.uri));
    e.resultEntries.forEach((r) => r.photoAssets.forEach((p) => uris.add(p.uri)));
  }
  return uris;
};

/** Removes photo files nothing in `state` refers to. A failed removal leaves a stray file, never a lost reference. */
async function removeFiles(storage: Storage, uris: Iterable<string>, state: FileState): Promise<void> {
  if (!storage.fs.rm) return;
  const kept = photoUris(state);
  for (const uri of new Set(uris)) {
    if (kept.has(uri) || !uri.startsWith(`${PHOTOS_DIR}/`)) continue;
    try {
      await storage.fs.rm(uri);
    } catch {
      // the file is already gone, or stays as a stray the next sweep removes
    }
  }
}

const swept = new WeakSet<object>();

/** Once per app run, before anything is copied in: files in the photos folder no record refers to (left by an abandoned draft) go. */
async function sweepStrays(storage: Storage, state: FileState): Promise<void> {
  if (swept.has(storage.fs)) return;
  swept.add(storage.fs);
  if (!storage.fs.readdir) return;
  let names: string[];
  try {
    names = await storage.fs.readdir(PHOTOS_DIR);
  } catch {
    return;
  }
  await removeFiles(storage, names.map((n) => `${PHOTOS_DIR}/${n}`), state);
}

/** Writes the state and reads the file back; anything but the same state is an error. */
async function write(storage: Storage, state: FileState): Promise<void> {
  const text = JSON.stringify(state);
  await storage.fs.atomicWriteFile(EXPERIMENT_FS_PATH, new TextEncoder().encode(text));
  const back = new TextDecoder().decode(await storage.fs.readFile(EXPERIMENT_FS_PATH));
  if (back !== text) throw new Error('The change could not be confirmed in storage, so it was not saved.');
}

/** The state; a missing file (and only that) is seeded once with the two examples. */
async function ready(storage: Storage): Promise<FileState> {
  const state = await read(storage);
  if (state.bootstrapped) {
    await sweepStrays(storage, state);
    return state;
  }
  const next: FileState = { bootstrapped: true, experiments: seedExperiments.map(clone) };
  await write(storage, next);
  await sweepStrays(storage, next);
  return next;
}

function fromFields(f: ExperimentFields) {
  return {
    title: f.title.trim(),
    category: f.category.trim() || 'General',
    hypothesis: f.hypothesis.trim(),
    procedure: f.procedure.trim(),
    dataPlan: f.dataPlan.trim(),
    observationsNotes: f.observationsNotes.trim(),
    notes: f.notes.trim(),
    conclusionNotes: f.conclusionNotes.trim(),
    plannedAttachmentCount: Math.max(0, Number(f.plannedAttachmentCount) || 0),
  };
}

export function listExperiments(storage: Storage): Promise<ExperimentRecord[]> {
  return serial(async () => byUpdated((await ready(storage)).experiments.map(clone)));
}

export function getExperimentById(id: string, storage: Storage): Promise<ExperimentRecord | null> {
  return serial(async () => {
    const found = (await ready(storage)).experiments.find((e) => e.id === id);
    return found ? clone(found) : null;
  });
}

export function createExperiment(
  fields: ExperimentFields,
  storage: Storage,
  options: { id: string; now: string; photoAssets?: ExperimentPhotoAsset[] },
): Promise<ExperimentRecord> {
  return serial(async () => {
    const state = await ready(storage);
    if (state.experiments.some((e) => e.id === options.id)) throw new Error('An experiment with this id exists.');
    const record: ExperimentRecord = {
      id: options.id,
      ...fromFields(fields),
      resultEntries: [],
      photoAssets: options.photoAssets ?? [],
      status: 'active',
      createdAt: options.now,
      updatedAt: options.now,
    };
    await write(storage, { ...state, experiments: [record, ...state.experiments] });
    return clone(record);
  });
}

/** Changes the editor's fields, keeping the stored status, results and photos. Null: no such record. */
export function updateExperiment(
  id: string,
  fields: ExperimentFields,
  storage: Storage,
  options: { now: string },
): Promise<ExperimentRecord | null> {
  return serial(async () => {
    const state = await ready(storage);
    const existing = state.experiments.find((e) => e.id === id);
    if (!existing) return null;
    const record: ExperimentRecord = { ...existing, ...fromFields(fields), updatedAt: options.now };
    await write(storage, { ...state, experiments: state.experiments.map((e) => (e.id === id ? record : e)) });
    return clone(record);
  });
}

/** Changes the status, keeping every field. Null: no such record. */
export function updateExperimentStatus(
  id: string,
  status: ExperimentStatus,
  storage: Storage,
  options: { now: string },
): Promise<ExperimentRecord | null> {
  return serial(async () => {
    const state = await ready(storage);
    const existing = state.experiments.find((e) => e.id === id);
    if (!existing) return null;
    const record: ExperimentRecord = { ...existing, status, updatedAt: options.now };
    await write(storage, { ...state, experiments: state.experiments.map((e) => (e.id === id ? record : e)) });
    return clone(record);
  });
}

export function deleteExperiment(id: string, storage: Storage): Promise<void> {
  return serial(async () => {
    const state = await ready(storage);
    const gone = state.experiments.find((e) => e.id === id);
    const next = { ...state, experiments: state.experiments.filter((e) => e.id !== id) };
    await write(storage, next);
    if (gone) await removeFiles(storage, photoUris({ ...state, experiments: [gone] }), next);
  });
}

/**
 * Empties the file and marks it seeded, so the examples are never put back. It does not read
 * first, so it also replaces a damaged file: the one deliberate way out.
 */
export function resetExperiments(storage: Storage): Promise<void> {
  return serial(async () => {
    const empty: FileState = { bootstrapped: true, experiments: [] };
    await write(storage, empty);
    swept.delete(storage.fs);
    await sweepStrays(storage, empty);
  });
}

// ---------------------------------------------------------------------------
// Result entries. Each runs through the same queue and read-back as every other write, changes
// only the one entry, and keeps the record's fields, status, photos and the entries' own photos.
// A result needs notes or photos; recordedAt is set once, when the entry is added.
// ---------------------------------------------------------------------------

export class ResultError extends Error {}

const withResults = (
  id: string,
  storage: Storage,
  now: string,
  change: (existing: ExperimentRecord) => ExperimentResultEntry[],
  after?: (before: ExperimentRecord, record: ExperimentRecord, next: FileState) => Promise<void>,
): Promise<ExperimentRecord | null> =>
  serial(async () => {
    const state = await ready(storage);
    const existing = state.experiments.find((e) => e.id === id);
    if (!existing) return null;
    const record: ExperimentRecord = { ...existing, resultEntries: change(existing), updatedAt: now };
    const next = { ...state, experiments: state.experiments.map((e) => (e.id === id ? record : e)) };
    await write(storage, next);
    if (after) await after(existing, record, next);
    return clone(record);
  });

/** Puts a new entry first. Null: no such record. */
export function addResultEntry(
  experimentId: string,
  entry: { id: string; recordedAt: string; notes: string; photoAssets?: ExperimentPhotoAsset[] },
  storage: Storage,
  options: { now: string },
): Promise<ExperimentRecord | null> {
  const notes = entry.notes.trim();
  const photoAssets = entry.photoAssets ?? [];
  if (notes === '' && photoAssets.length === 0) {
    return Promise.reject(new ResultError('Write some result notes or add a photo before saving.'));
  }
  return withResults(experimentId, storage, options.now, (existing) => {
    if (existing.resultEntries.some((r) => r.id === entry.id)) throw new ResultError('A result with this id exists.');
    return [{ id: entry.id, recordedAt: entry.recordedAt, notes, photoAssets }, ...existing.resultEntries];
  });
}

/** Changes one entry's notes only. Null: no such record. */
export function updateResultNotes(
  experimentId: string,
  resultId: string,
  notes: string,
  storage: Storage,
  options: { now: string },
): Promise<ExperimentRecord | null> {
  const text = notes.trim();
  return withResults(experimentId, storage, options.now, (existing) => {
    const entry = existing.resultEntries.find((r) => r.id === resultId);
    if (!entry) throw new ResultError('This result no longer exists.');
    if (text === '' && entry.photoAssets.length === 0) throw new ResultError('A result needs notes or photos.');
    return existing.resultEntries.map((r) => (r.id === resultId ? { ...r, notes: text } : r));
  });
}

/** Removes one entry. Null: no such record. */
export function deleteResultEntry(
  experimentId: string,
  resultId: string,
  storage: Storage,
  options: { now: string },
): Promise<ExperimentRecord | null> {
  return withResults(
    experimentId,
    storage,
    options.now,
    (existing) => {
      if (!existing.resultEntries.some((r) => r.id === resultId)) throw new ResultError('This result no longer exists.');
      return existing.resultEntries.filter((r) => r.id !== resultId);
    },
    (before, _record, next) =>
      removeFiles(storage, before.resultEntries.filter((r) => r.id === resultId).flatMap((r) => r.photoAssets.map((p) => p.uri)), next),
  );
}

// ---------------------------------------------------------------------------
// Photos. The files are copied into app:/data/photos by the caller's `produce`, inside the same turn
// of the queue as the metadata write, so the copy and the record change are never interleaved with
// another write. If the record cannot be written, the copies are removed again; a file is removed
// when its last reference goes, never while any experiment or result still names it.
// ---------------------------------------------------------------------------

export class PhotoRefused extends Error {}

type PhotoTarget = { experimentId: string; resultId: string }; // resultId '' = the experiment's own photos

const mapPhotos = (
  existing: ExperimentRecord,
  target: PhotoTarget,
  change: (photos: ExperimentPhotoAsset[], entry: ExperimentResultEntry | null) => ExperimentPhotoAsset[],
): Pick<ExperimentRecord, 'photoAssets' | 'resultEntries'> => {
  if (target.resultId === '') return { photoAssets: change(existing.photoAssets, null), resultEntries: existing.resultEntries };
  const entry = existing.resultEntries.find((r) => r.id === target.resultId);
  if (!entry) throw new ResultError('This result no longer exists.');
  return {
    photoAssets: existing.photoAssets,
    resultEntries: existing.resultEntries.map((r) => (r.id === target.resultId ? { ...r, photoAssets: change(r.photoAssets, r) } : r)),
  };
};

/** Copies photos in (via `produce`) and attaches them to the record or one of its results. Null: no such record. */
export function attachPhotos(
  target: PhotoTarget,
  produce: () => Promise<ExperimentPhotoAsset[]>,
  storage: Storage,
  options: { now: string },
): Promise<ExperimentRecord | null> {
  return serial(async () => {
    const state = await ready(storage);
    const existing = state.experiments.find((e) => e.id === target.experimentId);
    if (!existing) return null;
    if (target.resultId !== '' && !existing.resultEntries.some((r) => r.id === target.resultId)) {
      throw new ResultError('This result no longer exists.');
    }
    const added = await produce();
    try {
      const seen = new Set<string>();
      const parts = mapPhotos(existing, target, (photos) =>
        [...photos, ...added].filter((p) => (seen.has(p.id) ? false : (seen.add(p.id), true))),
      );
      const record: ExperimentRecord = { ...existing, ...parts, updatedAt: options.now };
      await write(storage, { ...state, experiments: state.experiments.map((e) => (e.id === record.id ? record : e)) });
      return clone(record);
    } catch (e) {
      // A successful write can be followed by a failed read-back. Only delete
      // copies after a fresh read proves that the persisted state does not use them.
      try {
        const persisted = await read(storage);
        if (persisted.bootstrapped) await removeFiles(storage, added.map((p) => p.uri), persisted);
      } catch {
        // An unknown write outcome must keep the files: they may be referenced.
      }
      throw e;
    }
  });
}

/** Detaches one photo; its file goes only when nothing else refers to it. Null: no such record. */
export function removePhoto(
  target: PhotoTarget,
  photoId: string,
  storage: Storage,
  options: { now: string },
): Promise<ExperimentRecord | null> {
  return serial(async () => {
    const state = await ready(storage);
    const existing = state.experiments.find((e) => e.id === target.experimentId);
    if (!existing) return null;
    let removed: ExperimentPhotoAsset | undefined;
    const parts = mapPhotos(existing, target, (photos, entry) => {
      removed = photos.find((p) => p.id === photoId);
      if (!removed) throw new PhotoRefused('This photo is already gone.');
      const rest = photos.filter((p) => p.id !== photoId);
      if (entry && rest.length === 0 && entry.notes.trim() === '') throw new PhotoRefused('A result needs notes or photos.');
      return rest;
    });
    const record: ExperimentRecord = { ...existing, ...parts, updatedAt: options.now };
    const next = { ...state, experiments: state.experiments.map((e) => (e.id === record.id ? record : e)) };
    await write(storage, next);
    if (removed) await removeFiles(storage, [removed.uri], next);
    return clone(record);
  });
}

/** Copies photos in for a form not yet saved (New, or a result draft); nothing refers to them until it is. */
export function stagePhotos(produce: () => Promise<ExperimentPhotoAsset[]>, storage: Storage): Promise<ExperimentPhotoAsset[]> {
  return serial(async () => {
    await ready(storage);
    return produce();
  });
}

/** Drops a staged photo's file, unless a record has meanwhile taken it. */
export function discardStagedPhoto(uri: string, storage: Storage): Promise<void> {
  return serial(async () => removeFiles(storage, [uri], await ready(storage)));
}

